  const conflicts = sessions
    .filter((session) => session.conflict)
    .map((session) => session.id);

  return (
    <div className="flex-col-gap-3 items-start">
      <Button variant="base" size="sm" onClick={() => setExpanded(conflicts)}>
        Show conflicts
