      <SessionTable
        caption="Schedule"
        data={sessions}
        rowKey={(session) => session.id}
      >
        <SessionTable.Expansion
          value={expanded}
          onChange={setExpanded}
          isRowExpandable={(session) => Boolean(session.conflict)}
        >
          {(session) => <p>{session.conflict}</p>}
        </SessionTable.Expansion>
        <SessionTable.Column
          id="title"
          rowHeader
          title="Session"
          dataKey="title"
          width={220}
        />
        <SessionTable.Column
          id="startsAt"
          title="Starts"
          dataKey="startsAt"
          width={90}
        />
        <SessionTable.Column
          id="room"
          title="Room"
          dataKey="room"
          width={120}
        />
      </SessionTable>
    </div>
  );
};

/**
