    );

  return (
    <EventTable
      caption="Events"
      data={rows}
      rowKey={(event) => event.id}
      emptyMessage="No events match the filters."
      onRowClick={(_, click) => click.currentTarget.querySelector('a')?.click()}
    >
      <EventTable.Sort defaultValue={{ columnId: 'date', direction: 'asc' }} />
      <EventTable.Column
        id="name"
        rowHeader
        title="Name"
        dataKey="name"
        width={220}
        sortable
        filter={{ type: 'text' }}
      >
        {(name, event) => <Link href={`/events/${event.id}`}>{name}</Link>}
      </EventTable.Column>
      <EventTable.Column
        id="organizer"
        title="Organizer"
        dataKey="organizer"
        width={180}
        sortable
        filter={{ type: 'enum', options: organizerOptions }}
      >
        {(organizer) => (
          <div className="flex-row-gap-2 items-center min-w-0">
            <Avatar size="sm" name={organizer} />
            <Truncate>{organizer}</Truncate>
          </div>
        )}
      </EventTable.Column>
      <EventTable.Column
        id="ticketPrice"
        title="Ticket price"
        dataKey="ticketPrice"
        width={130}
        align="right"
        sortable
        filter={{ type: 'number' }}
      >
        {(ticketPrice) => currency.format(ticketPrice)}
      </EventTable.Column>
      <EventTable.Column
        id="date"
        title="Date"
        dataKey="date"
        width={130}
        sortable
      >
        {(date) => day.format(new Date(date))}
      </EventTable.Column>
      <EventTable.Column
        id="status"
        title="Status"
        dataKey="status"
        width={120}
      >
        {(status) => (
          <Tag size="xs" variant={statusTag[status]}>
            {status}
          </Tag>
        )}
      </EventTable.Column>
      <EventTable.Column
        id="actions"
        title={<span className="sr-only">Actions</span>}
        width={48}
        align="right"
      >
        {(_, event) => (
          <Dropdown
            menu={
              <>
                <Dropdown.Item
                  leftIcon={<Link2 />}
