// Covers: DateInput, Input, NumberInput, PasswordInput, QuantitySelector, SearchInput

/**
 * Input: a single-line text field. `onChange` gets the text, not an event. With
 * `delay`, the text shows at once and `onChange` waits for a pause in typing.
 * PasswordInput, SearchInput and NumberInput are the fields for those values;
 * QuantitySelector is a small count stepped with − and + or typed.
 * In a `useForm` form, every field renders through `Controller`, and
 * `{...field}` gives it its name, value, `onChange`, `required` mark, `error`
 * and focus on a failed submit.
 *
 * When not to use:
 * - A password: PasswordInput. A search: SearchInput. A number: NumberInput.
 *   A small count, like an item's quantity: QuantitySelector.
 * - A choice from a list: Select. A date: DateInput. A time: FormControl around
 *   the native input.
 *
 * Pitfalls:
 * - Every field needs a name: `label`, `aria-label` or `aria-labelledby`. A
 *   placeholder is not a name.
 * - A button that acts on the field's value, such as Send, Apply or Move,
 *   goes in its `action`, in a form or out of one, such as a filter bar or a
 *   toolbar. A button beside the field in a flex row lines up with the label,
 *   not the box.
 * - Set `required` through the `rules` of `Controller`, which also marks the
 *   field. `{...field}` overwrites a `required` or `error` given before it, so
 *   spread it first when you override either.
 * - Report a server's error with `setError`, so it shows on the field.
 * - An error shows below the help text, which stays: the message says what went
 *   wrong ("Too short"), the help text what's asked.
 * - `error={true}` only styles the field. Pass a message unless the same text
 *   shows elsewhere.
 * - Don't put a live counter in `helpText`: it announces on every key. Use
 *   `labelRightSlot`.
 * - SearchInput's `loading` locks typing unless `disableWhileLoading={false}`.
 * - NumberInput shows a text keyboard on phones unless `min` is 0 or more or
 *   `allowNegative={false}`: number keypads have no minus key.
 * - QuantitySelector starts at `min`, 1 unless set. Give `maxReason` the
 *   reason the count stops, such as "Only 5 in stock", and name it for its
 *   item: `aria-label="Quantity of …"`.
 */
import { Button, IconButton } from '@packages/ui/Button';
import { Controller, Form } from '@packages/ui/Form';
import {
  DateInput,
  Input,
  NumberInput,
  PasswordInput,
  QuantitySelector,
  SearchInput,
} from '@packages/ui/Input';
import { Link } from '@packages/ui/Link';
import { AtSign, Copy } from 'lucide-react';
import React, { useRef, useState } from 'react';
import { useForm } from 'react-hook-form';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const takenAddresses = ['launch', 'meetup'];
const venues = ['Harbor Hall', 'Old Mill', 'Riverside Pavilion', 'The Loft'];
const events = ['Launch party', 'Community meetup', 'Design review'];

// Stand in for requests to a server.
const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
const saveContact = (contact: Contact) => wait(600).then(() => contact);
const saveTitle = (title: string) => wait(300).then(() => title);
const isAddressFree = (address: string) =>
  wait(400).then(() => !takenAddresses.includes(address));
const signIn = (password: string) =>
  wait(600).then(() => password === 'correct-horse');
const reserveAddress = (address: Address) => wait(400).then(() => address);
const addGuests = (guests: Guests) => wait(400).then(() => guests);
const createAccount = (account: SignUp) => wait(600).then(() => account);
const searchVenues = (search: string) =>
  wait(500).then(() =>
    venues.filter((venue) =>
      venue.toLowerCase().includes(search.toLowerCase()),
    ),
  );

// Usage: the patterns to copy.
const MAX_TAGLINE = 60;
const SHARE_LINK = 'https://events.example.com/launch-party';

type Contact = { name: string; email: string; phone: string };

/**
 * A contact form: `rules` validate, `type` brings the right phone keyboard, and
 * the submit button shows it is saving through `loadingWithReason`.
 */
const ContactForm = () => {
  const {
    control,
    handleSubmit,
    formState: { isSubmitting },
  } = useForm<Contact>({ defaultValues: { name: '', email: '', phone: '' } });

  return (
    <Form
      onSubmit={handleSubmit(saveContact)}
      actions={
        <Button
          type="submit"
          loadingWithReason={isSubmitting ? 'Saving your contact' : undefined}
        >
          Save
        </Button>
      }
    >
      <Controller
        name="name"
        control={control}
        rules={{ required: 'Enter your name' }}
      >
        {({ field }) => <Input label="Name" autoComplete="name" {...field} />}
      </Controller>
      <Controller
        name="email"
        control={control}
        rules={{
          required: 'Enter your email',
          pattern: {
            value: /^\S+@\S+\.\S+$/,
            message: 'Enter an email like name@example.com',
          },
        }}
      >
        {({ field }) => (
          <Input
            label="Email"
            type="email"
            autoComplete="email"
            leftIcon={<AtSign />}
            helpText="For receipts only"
            {...field}
          />
        )}
      </Controller>
      <Controller name="phone" control={control}>
        {({ field }) => (
          <Input
            label="Phone"
            type="tel"
            autoComplete="tel"
            hint="Only used if the venue needs to reach you"
            {...field}
          />
        )}
      </Controller>
    </Form>
  );
};

/**
 * Saved as the user types: `delay` holds `onChange` until typing pauses for
 * 500ms. A new `value` from the parent, like the suggested title, replaces the
 * text and drops an unsent save.
 */
const AutosavedTitle = () => {
  const [title, setTitle] = useState('Launch party');
  const [status, setStatus] = useState('All changes saved');

  const save = (next: string) => {
    setTitle(next);
    setStatus('Saving');
    saveTitle(next).then(() => setStatus('All changes saved'));
  };

  return (
    <div className="flex-col-gap-2 items-start">
      <Input
        label="Event title"
        autoComplete="off"
        delay={500}
        value={title}
        onChange={save}
      />
      <Button variant="base" onClick={() => save('Product launch')}>
        Use suggested title
      </Button>
      <p role="status">{status}</p>
    </div>
  );
};

/** `hint` explains the field in a tooltip, `placeholder` shows an example. */
const PromoCode = () => {
