        label="From"
        autoComplete="off"
        allowNegative={false}
        leftAddOn="€"
        error={isInverted}
        value={from}
        onChange={setFrom}
      />
      <NumberInput
        label="To"
        autoComplete="off"
        allowNegative={false}
        leftAddOn="€"
        error={isInverted && 'To must not be below From'}
        value={to}
        onChange={setTo}
      />
    </div>
  );
};

/**
 * Whole numbers within a range: `allowDecimal={false}`, `min` and `max` (blur
