};

/** `type="url"` brings the URL keyboard on phones. */
const StreamLink = () => {
  const [link, setLink] = useState('');

  return (
    <Input
      label="Stream link"
      type="url"
      placeholder="https://"
      autoComplete="off"
      value={link}
      onChange={setLink}
    />
  );
};

/**
 * A value to copy, not edit: `readOnlyWithReason` says why; a copy button sits
 * in `rightAddOn`.
 */
const ShareLink = () => {
  const copy = () => navigator.clipboard.writeText(SHARE_LINK);

  return (
    <Input
      label="Share link"
      readOnlyWithReason="The link is generated for you"
      autoComplete="off"
      value={SHARE_LINK}
      onChange={() => undefined}
      rightAddOn={
        <IconButton
          tooltip="Copy share link"
          variant="base"
          look="ghost"
          size="xs"
          onClick={copy}
        >
          <Copy />
        </IconButton>
      }
