/**
 * A field that can't be used yet: `disabledWithReason` says what unlocks it.
 */
const RegistrationCode = () => (
  <Input
    label="Registration code"
    disabledWithReason="Codes open when registration starts"
    autoComplete="off"
    value=""
    onChange={() => undefined}
  />
);

/**
 * Content on its way: `loadingWithReason` shows a spinner and says what loads.
 */
const DraftTitle = () => (
  <Input
    label="Title"
    loadingWithReason="Loading your draft"
    autoComplete="off"
    value=""
    onChange={() => undefined}
  />
);

type Address = { address: string };

/**
 * Checking a value on the server: an async `validate` rule runs on each change
 * (`mode: 'onChange'`), and `delay` makes a change a pause in typing. `loading`
 * follows `isValidating`; `success` confirms the address.
 */
const EventAddressField = () => {
  const {
    control,
    handleSubmit,
    formState: { isSubmitting },
  } = useForm<Address>({ mode: 'onChange', defaultValues: { address: '' } });

  return (
    <Form
      onSubmit={handleSubmit(reserveAddress)}
      actions={
        <Button
          type="submit"
          loadingWithReason={isSubmitting ? 'Reserving the address' : undefined}
        >
          Reserve
        </Button>
      }
    >
      <Controller
        name="address"
        control={control}
        rules={{
          required: 'Choose an address',
          validate: async (address) =>
            (await isAddressFree(address)) || 'That address is taken',
        }}
      >
        {({ field, fieldState }) => (
          <Input
            label="Event address"
            autoComplete="off"
            delay={500}
            // Typing stays open while the check runs.
            loading={fieldState.isValidating}
            disableWhileLoading={false}
            success={
              field.value && !fieldState.error && !fieldState.isValidating
                ? 'Available'
                : undefined
            }
            {...field}
          />
        )}
      </Controller>
    </Form>
  );
};

/**
 * Adding items from the keyboard: Enter adds, and `ref` reaches the input to
 * return focus after each add.
 */
const SpeakerList = () => {
  const [speakers, setSpeakers] = useState<string[]>([]);
  const [name, setName] = useState('');
  const inputRef = useRef<HTMLElement>(null);

  const add = () => {
    if (!name.trim()) return;
    setSpeakers([...speakers, name.trim()]);
    setName('');
    inputRef.current?.focus();
  };

  return (
    <div className="flex-col-gap-2 items-start">
      <Input
        ref={inputRef}
        label="Speaker name"
        autoComplete="off"
        value={name}
        onChange={setName}
        onKeyDown={(event) => {
          if (event.key !== 'Enter') return;
          event.preventDefault();
          add();
        }}
      />
      <Button variant="base" onClick={add}>
        Add speaker
      </Button>
      <ul>
        {speakers.map((speaker) => (
          <li key={speaker}>{speaker}</li>
        ))}
      </ul>
    </div>
  );
};

/**
 * Two numbers that must be in order. `error={true}` styles From alone; the
 * message on To is the one announced. `allowNegative={false}` keeps the number
 * keypad on phones.
 */
const PriceFilter = () => {
  const [from, setFrom] = useState<number | null>(20);
  const [to, setTo] = useState<number | null>(10);
  const isInverted = from !== null && to !== null && from > to;

  return (
    <div className="flex-row-gap-4 flex-wrap items-start">
      <NumberInput
        label="From"
        autoComplete="off"
        allowNegative={false}
        leftAddOn="€"
        error={isInverted}
        value={from}
        onChange={setFrom}
      />
      <NumberInput
        label="To"
        autoComplete="off"
        allowNegative={false}
        leftAddOn="€"
        error={isInverted && 'To must not be below From'}
        value={to}
        onChange={setTo}
      />
    </div>
  );
};

/**
 * Whole numbers within a range: `allowDecimal={false}`, `min` and `max` (blur
 * moves the number into them), `delay` to wait for a pause. `warning` flags an
 * allowed value worth a look.
 */
const VenueCapacity = () => {
  const [capacity, setCapacity] = useState<number | null>(120);

  return (
    <NumberInput
      label="Venue capacity"
      autoComplete="off"
      allowDecimal={false}
      min={1}
      max={500}
      step={10}
      delay={500}
      warning={
        capacity !== null && capacity > 400
          ? 'Large venues need a safety plan'
          : undefined
      }
      value={capacity}
      onChange={setCapacity}
    />
  );
};

/**
 * Negative values allowed: a shift of the agenda in minutes, earlier or later.
 */
const AgendaShift = () => {
  const [minutes, setMinutes] = useState<number | null>(-15);

  return (
    <NumberInput
      label="Shift agenda by (minutes)"
      autoComplete="off"
      min={-120}
      max={120}
      step={5}
      value={minutes}
      onChange={setMinutes}
    />
  );
};

type Guests = { guests: number | null };

/**
 * In a form, the empty number is `null`, so `required` and `min` rules apply.
 */
const GuestCount = () => {
  const {
    control,
    handleSubmit,
    formState: { isSubmitting },
  } = useForm<Guests>({ defaultValues: { guests: null } });

  return (
    <Form
      onSubmit={handleSubmit(addGuests)}
      actions={
        <Button
          type="submit"
          loadingWithReason={isSubmitting ? 'Adding your guests' : undefined}
        >
          Add guests
        </Button>
      }
    >
      <Controller
        name="guests"
        control={control}
        rules={{
          required: 'Enter how many guests are coming',
          min: { value: 1, message: 'Bring at least 1 guest' },
        }}
      >
        {({ field }) => (
          <NumberInput
            label="Guests"
            autoComplete="off"
            min={0}
            max={10}
            {...field}
          />
        )}
      </Controller>
    </Form>
  );
};

type SignIn = { password: string };

/**
 * Signing in: `autoComplete="current-password"` lets password managers fill it,
 * `labelRightSlot` holds the recovery link, and a failed sign-in goes through
 * `setError`.
 */
const SignInForm = () => {
  const {
    control,
    handleSubmit,
    setError,
    formState: { isSubmitting },
  } = useForm<SignIn>({ defaultValues: { password: '' } });

  const submit = async ({ password }: SignIn) => {
    if (!(await signIn(password))) {
      setError('password', { message: 'That password is not right' });
    }
  };

  return (
    <Form
      onSubmit={handleSubmit(submit)}
      actions={
        <Button
          type="submit"
          loadingWithReason={isSubmitting ? 'Signing you in' : undefined}
        >
          Sign in
        </Button>
      }
    >
      <Controller
        name="password"
        control={control}
        rules={{ required: 'Enter your password' }}
      >
        {({ field }) => (
          <PasswordInput
            label="Password"
            autoComplete="current-password"
            labelRightSlot={
              <Link href="/forgot-password">Forgot password?</Link>
            }
            {...field}
          />
        )}
      </Controller>
    </Form>
  );
};

type SignUp = { password: string; confirm: string };

/**
 * Creating a password: `new-password` offers a generated one, `helpText` states
 * the requirement and stays above any error. The confirmation compares with
 * `getValues`, and `deps` re-checks it when the first field changes.
 */
const SignUpPassword = () => {
  const {
    control,
    handleSubmit,
    getValues,
    formState: { isSubmitting },
  } = useForm<SignUp>({ defaultValues: { password: '', confirm: '' } });

  return (
    <Form
      onSubmit={handleSubmit(createAccount)}
      actions={
        <Button
          type="submit"
          loadingWithReason={isSubmitting ? 'Creating your account' : undefined}
        >
          Create account
        </Button>
      }
    >
      <Controller
        name="password"
        control={control}
        rules={{
          required: 'Use 8 or more characters',
          minLength: { value: 8, message: 'Use 8 or more characters' },
          deps: ['confirm'],
        }}
      >
        {({ field }) => (
          <PasswordInput
            label="Create password"
            autoComplete="new-password"
            helpText="Use 8 or more characters"
            {...field}
          />
        )}
      </Controller>
      <Controller
        name="confirm"
        control={control}
        rules={{
          required: 'Repeat the password',
          validate: (confirm) =>
            confirm === getValues('password') || 'The passwords do not match',
        }}
      >
        {({ field }) => (
          <PasswordInput
            label="Confirm password"
            autoComplete="new-password"
            {...field}
          />
        )}
      </Controller>
    </Form>
  );
};

/**
 * Filtering a list: SearchInput shows what's typed at once and sends it after a
 * pause. Escape and the clear button empty it. Give it a visible label, wrap it
 * in `role="search"`, and announce the count.
 */
const EventSearch = () => {
  const [search, setSearch] = useState('');
  const matches = events.filter((event) =>
    event.toLowerCase().includes(search.toLowerCase()),
  );

  return (
    <div className="flex-col-gap-2">
      <div role="search">
        <SearchInput
          label="Find an event"
          placeholder="Search events"
          value={search}
          onChange={setSearch}
        />
      </div>
      <p role="status">
        {matches.length} {matches.length === 1 ? 'event' : 'events'}
      </p>
      <ul>
        {matches.map((event) => (
          <li key={event}>{event}</li>
        ))}
      </ul>
    </div>
  );
};

/**
 * Searching on the server: `loading` shows while results load, and
 * `disableWhileLoading={false}` keeps typing open. Each answer keeps the text
 * it answers: one for older text is dropped, and loading lasts until the answer
 * matches the last text typed.
 */
const VenueSearch = () => {
  const [search, setSearch] = useState('');
  const [answer, setAnswer] = useState({ search: '', results: venues });
  const latest = useRef('');
  const loading = answer.search !== search;

  const find = (next: string) => {
    setSearch(next);
    latest.current = next;
    void searchVenues(next).then((results) => {
      if (latest.current === next) setAnswer({ search: next, results });
    });
  };

  return (
    <div className="flex-col-gap-2">
      <div role="search">
        <SearchInput
          label="Find a venue"
          placeholder="Search venues"
          // Typing stays open while results load.
          loading={loading}
          disableWhileLoading={false}
          value={search}
          onChange={find}
        />
      </div>
      <ul>
        {answer.results.map((venue) => (
          <li key={venue}>{venue}</li>
        ))}
      </ul>
    </div>
  );
};

/**
 * A day on the browser's own picker: `value` is the day as `2026-11-07`, `''`
 * while empty, and `min` and `max` bound it the same way.
 */
const EventDay = () => {
  const [day, setDay] = useState('');
  return (
    <DateInput
      label="Event day"
      autoComplete="off"
      min="2026-01-01"
      value={day}
      onChange={setDay}
    />
  );
};

/**
 * A button beside the field: `action` lines it up with the box, so the label
 * stays above both and a message below both. The button says why it waits.
 */
const InviteByEmail = () => {
  const [email, setEmail] = useState('');
  const [sent, setSent] = useState('');
  const invalid = email !== '' && !email.includes('@');

  return (
    <div className="flex-col-gap-2">
      <Input
        label="Invite by email"
        type="email"
        autoComplete="off"
        value={email}
        onChange={setEmail}
        error={invalid ? 'Enter an email like name@example.com' : undefined}
        action={
          <Button
            disabledWithReason={
              email === '' || invalid ? 'Enter an email first' : undefined
            }
            onClick={() => setSent(`Invited ${email}`)}
          >
            Send
          </Button>
        }
      />
      <p role="status">{sent}</p>
    </div>
  );
};

/** A count stepped or typed, such as an item's quantity, with the reason it stops. */
