// packages/ui/src/Tag/Tag.recipe.tsx
// Covers: Tag

/**
 * Tag: a short label that only informs: a status, a category, a count, or a
 * chosen filter the user removes with its close button (`closable`). The
 * label stays on one line; cut text shows in full on hover.
 *
 * When not to use:
 * - Anything the user clicks to turn on or off: Chip. A Tag is never pressed.
 * - An action: Button.
 * - Choosing from a list of options: Select, or ChipGroup for a few.
 *
 * Pitfalls:
 * - Removing a tag removes the button that had focus. Keep each close button
 *   in a ref (`closeRef`) and move focus to the next tag's before removing.
 * - A closable tag's `tooltip` shows on its close button, on hover and
 *   focus. On a tag that can't close, it shows on hover only, so put nothing
 *   the user must know there.
 * - A bare count means nothing read aloud: give it a unit, in visually
 *   hidden text if the visible one is dropped.
 * - `closeTabIndex={-1}` is only for a widget that moves focus between its
 *   tags itself, like a toolbar with arrow keys. Otherwise every close
 *   button must stay reachable by Tab.
 * - Say why a tag can't be removed: `disabledWithReason`, not `disabled`.
 */
import { Button } from '@packages/ui/Button';
import { Tag } from '@packages/ui/Tag';
import { CircleCheck, MapPin } from 'lucide-react';
import React, { useRef, useState } from 'react';

// Usage: the patterns to copy.
/** Status: a status variant, `size="xs"` in table rows and dense lists. */
const Status = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Tag size="xs" variant="success" leftIcon={<CircleCheck />}>
      Paid
    </Tag>
    <Tag size="xs" variant="warning">
      Pending
    </Tag>
    <Tag size="xs" variant="error">
      Refunded
    </Tag>
    <Tag size="xs" variant="info">
      Waitlist
    </Tag>
  </div>
);

/**
 * Chosen filters: `closable` with `onClose` removes one. Its close button is
 * read as "Remove" and the label, and `closeRef` lets the caller move focus
 * to the next tag's button (or to "Reset filters" after the last) before the
 * removed one disappears. `disabledWithReason` keeps one that can't be
 * removed and says why on hover and focus.
 */
const ChosenFilters = () => {
  const [teams, setTeams] = useState(['Design', 'Engineering', 'Sales']);
  const closeButtons = useRef(new Map<string, HTMLButtonElement>());
  const resetRef = useRef<HTMLButtonElement>(null);

  const remove = (index: number) => {
    const neighbor = teams[index + 1] ?? teams[index - 1];
    const next = neighbor && closeButtons.current.get(neighbor);

    (next || resetRef.current)?.focus();
    setTeams((current) => current.filter((_, i) => i !== index));
  };

  return (
    <div className="flex-col-gap-2 items-start">
      <ul aria-label="Chosen teams" className="flex-row-gap-2 flex-wrap">
        <li>
          <Tag closable disabledWithReason="Set by your workspace">
            Region: Europe
          </Tag>
        </li>
        {teams.map((team, index) => (
          <li key={team}>
            <Tag
              closable
              closeRef={(node) => {
                if (node) closeButtons.current.set(team, node);
                return () => {
                  closeButtons.current.delete(team);
                };
              }}
              onClose={() => remove(index)}
            >
              {team}
            </Tag>
          </li>
        ))}
      </ul>
      <Button
        ref={resetRef}
        variant="base"
        look="ghost"
        onClick={() => setTeams([])}
      >
        Reset filters
      </Button>
    </div>
  );
};

/**
 * Icon and count: `rightIcon` follows the label, and `leftAddOn` takes an
 * element before it. The unit is in visually hidden text, so the number is
 * read with its meaning and the visible number is skipped.
 */
const IconsAndCount = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Tag rightIcon={<MapPin />}>Berlin</Tag>
    <Tag variant="default" leftAddOn={<span aria-hidden>12</span>}>
      Engineering
      <span className="sr-only"> (12 events)</span>
    </Tag>
  </div>
);

/**
 * Tooltip: more detail on hover. A tag that can't close takes no focus, so
 * keyboard and touch users never see it: only extra detail goes there. On a
 * closable tag the tooltip moves to the close button and shows on focus too.
 */
const WithTooltip = () => (
  <Tag variant="warning" tooltip="Fewer than 10 tickets left">
    Almost full
  </Tag>
);

export default function TagRecipe() {
  return (
    <div className="flex-col-gap-6">
      <Status />
      <ChosenFilters />
      <IconsAndCount />
      <WithTooltip />
    </div>
  );
}

// packages/ui/src/Numeral/Numeral.recipe.tsx
// Covers: Numeral

/**
 * Numeral: a number the user reads and compares, such as a count, a total,
 * a statistic or a table's figures. It sets the digits in the theme's mono
 * font, so they line up in a column and a count that changes doesn't move
 * what sits beside it. A currency sign, a unit or words in it keep the text's
 * font. Size, weight and color come from around it.
 *
 * When not to use:
 * - A number inside a sentence ("3 books left to read"): it is part of the
 *   text and stays in the text's font.
 * - A date, a time or a phone number: people read them as text.
 *
 * Pitfalls:
 * - Format the number before you pass it: Numeral only sets its font. Use
 *   `toLocaleString` or `Intl.NumberFormat` for separators and currency.
 * - Keep the label outside: "Pages read" is text, only the figure is a
 *   Numeral. A unit that belongs to the figure, like € or %, goes inside;
 *   Numeral keeps it in the text's font. Never split a figure into a
 *   Numeral for the digits and text for the unit yourself.
 */
import { IconButton } from '@packages/ui/Button';
import { Numeral } from '@packages/ui/Numeral';
import {
  DescriptionDetails,
  DescriptionList,
  DescriptionTerm,
} from '@packages/ui/Typography';
import { Minus, Plus } from 'lucide-react';
import React, { useState } from 'react';

// Setup: stand-ins for your app's data, not part of the pattern.
const totals = [
  { label: 'Groceries', amount: 1249.5 },
  { label: 'Rent', amount: 950 },
  { label: 'Transport', amount: 86.25 },
];
const euros = new Intl.NumberFormat('en-IE', {
  style: 'currency',
  currency: 'EUR',
});

// Usage: the patterns to copy.
/** A count that changes: the buttons beside it stay where they are. */
const Counter = () => {
  const [count, setCount] = useState(9);
  return (
    <div className="flex-row-gap-2 items-center">
      <IconButton tooltip="Decrease" onClick={() => setCount(count - 1)}>
        <Minus />
      </IconButton>
      <Numeral aria-live="polite">{count}</Numeral>
      <IconButton tooltip="Increase" onClick={() => setCount(count + 1)}>
        <Plus />
      </IconButton>
    </div>
  );
};

/** A statistic: the figure takes its size from the element around it. */
const Statistic = () => (
  <div className="flex-col-gap-1">
    <span>Pages read this week</span>
    <span className="text-heading">
      <Numeral>{(1834).toLocaleString('en')}</Numeral>
    </span>
  </div>
);

/** Totals in a column: aligned to the end, the digits line up. */
const Totals = () => (
  <DescriptionList>
    {totals.map(({ label, amount }) => (
      <div key={label}>
        <DescriptionTerm>{label}</DescriptionTerm>
        <DescriptionDetails className="text-right">
          <Numeral>{euros.format(amount)}</Numeral>
        </DescriptionDetails>
      </div>
    ))}
  </DescriptionList>
);

export default function NumeralRecipe() {
  return (
    <div className="flex-col-gap-6 items-start">
      <Counter />
      <Statistic />
      <Totals />
    </div>
  );
}

// packages/ui/src/Link/Link.recipe.tsx
// Covers: Link

/**
 * Link: text that takes the user to another page: another site, an email
 * (`mailto:`), a phone number (`tel:`) or a file. Inside text it has a dotted
 * line instead of an underline; a link that works as a control, such as a way
 * back, a breadcrumb or a navigation item, is `look="plain"`. In the Next
 * app, a route of the app is the app's NextLink, which looks the same and
 * navigates without reloading the page.
 *
 * When not to use:
 * - An action (save, delete, open a menu): Button. A link goes somewhere.
 * - A route of the Next app: its NextLink. One that must look like a button
 *   is `Button as={NextLink}`.
 * - A whole card that opens a page: Card with `stretchLink`.
 *
 * Pitfalls:
 * - The dotted line is for a link inside text only. A link that stands on its
 *   own as a control, such as a way back, a breadcrumb, a navigation item or a
 *   footer's links, is `look="plain"`.
 * - In the Next app, a route as Link reloads the whole page: use NextLink.
 * - `target="_blank"` needs `rel="noopener noreferrer"` and text saying it
 *   opens a new tab.
 * - Link text must make sense alone ("Event guidelines", not "Click here").
 * - Say why a link is disabled: `disabledWithReason` keeps it focusable and
 *   shows the reason on focus; a plain `disabled` link leaves the tab order.
 */
import { Link } from '@packages/ui/Link';
import React from 'react';

// Usage: the patterns to copy.
/** In a sentence: it sits inline and wraps with the text around it. */
const InText = () => (
  <p>
    Read the{' '}
    <Link href="https://example.com/code-of-conduct">code of conduct</Link>{' '}
    before you register.
  </p>
);

/**
 * Another site: Link. `target="_blank"` opens a new tab, so `rel` keeps the
 * new page from reaching this one, and visually hidden text tells screen
 * reader users.
 */
const ExternalSite = () => (
  <Link
    href="https://example.com/venues/harbor-hall"
    target="_blank"
    rel="noopener noreferrer"
  >
    Harbor Hall venue page
    <span className="sr-only"> (opens in a new tab)</span>
  </Link>
);

/**
 * A link that works as a control, here a footer's links: `look="plain"`, since
 * its place already says it is a link. The dotted line stays for links inside
 * text.
 */
const ControlLinks = () => (
  <nav aria-label="Help" className="flex-row-gap-4 flex-wrap">
    <Link look="plain" href="https://example.com/help">
      Help center
    </Link>
    <Link look="plain" href="https://example.com/status">
      Service status
    </Link>
  </nav>
);

/** An email address: `mailto:` opens the user's mail app. */
const Email = () => (
  <Link href="mailto:organizers@example.com">Email the organizers</Link>
);

/** A phone number: `tel:` offers to call it on a phone. */
const Phone = () => <Link href="tel:+31201234567">Call the venue</Link>;

/** A file: `download` saves it instead of opening it. */
const Download = () => (
  <Link href="/files/schedule.pdf" download>
    Download the schedule (PDF)
  </Link>
);

/**
 * Disabled with a reason: it can't be followed, and hovering or focusing it
 * says why.
 * `disabledWithReason` on its own disables it; `disabled` disables it
 * silently, for a link whose reason is obvious from the screen.
 */
const DisabledWithReason = () => (
  <Link
    href="/files/attendance-report.pdf"
    download
    disabledWithReason="Ready once the event has ended"
  >
    Attendance report (PDF)
  </Link>
);

export default function LinkRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <InText />
      <ExternalSite />
      <ControlLinks />
      <Email />
      <Phone />
      <Download />
      <DisabledWithReason />
    </div>
  );
}

