// web/app/components/NotFound/NotFound.recipe.tsx
// Covers: NotFound

/**
 * NotFound: a record's page when its id finds nothing. A title naming what
 * is missing as the page's H1, one line on why, and the way back to the
 * list, the same on every record's page.
 *
 * When not to use:
 * - An empty list: the list's own empty state, with the action that fills it.
 * - A route the app doesn't have: Next's own not-found page.
 *
 * Pitfalls:
 * - It replaces the whole page, PageHeader included: return it alone.
 * - Name the record by its noun in the title, "Order not found", never "Not
 *   found" alone.
 */
import { NotFound } from '@app/components/NotFound';
import React from 'react';

// Usage: the patterns to copy.
/** The page of an order whose id matches none. */
const MissingOrder = () => (
  <NotFound
    title="Order not found"
    description="It may have been deleted, or the link is wrong."
    back={{ label: 'Back to orders', href: '/orders' }}
  />
);

export default function NotFoundRecipe() {
  return <MissingOrder />;
}

// web/app/components/NextLink/NextLink.recipe.tsx
// Covers: NextLink

/**
 * NextLink: a link to a route of this app (`/events/42`). Next.js navigates
 * to it without reloading the page and prefetches it. It looks like Link,
 * which is for other sites, emails, phone numbers and files: a dotted line
 * inside text, `look="plain"` as a control.
 *
 * When not to use:
 * - Another site, an email, a phone number or a file: Link.
 * - An action (save, delete, open a menu): Button. A link goes somewhere.
 * - A whole card that opens a page: Card with `stretchLink`, and a plain
 *   NextLink on its title.
 *
 * Pitfalls:
 * - The dotted line is for a link inside text only. A link that stands on its
 *   own as a control, such as a way back, a breadcrumb or a navigation item,
 *   is `look="plain"`.
 * - A route as Link reloads the whole page: use NextLink.
 * - A route that must look like a button is `Button as={NextLink}`, not a
 *   bare NextLink, whose dotted line clashes with a button.
 * - Mark the current page in a nav with `aria-current="page"`.
 * - Say why a link is disabled: `disabledWithReason` keeps it focusable and
 *   shows the reason on focus; a plain `disabled` link leaves the tab order.
 */
import { NextLink } from '@app/components/NextLink';
import { Button } from '@packages/ui/Button';
import { Input } from '@packages/ui/Input';
import { Plus } from 'lucide-react';
import React, { useState } from 'react';

// Usage: the patterns to copy.
/** In a sentence: it sits inline and wraps with the text around it. */
const InText = () => (
  <p>
    Read the <NextLink href="/guidelines">event guidelines</NextLink> before you
    publish.
  </p>
);

/**
 * Takes `replace`, `scroll`, `prefetch` and `onNavigate`, as Next.js's `Link`
 * does; `scroll={false}` keeps the scroll position.
 */
const KeepScroll = () => (
  <NextLink href="/events/42" scroll={false}>
    Design review
  </NextLink>
);

/**
 * A way back that replaces the current history entry instead of adding
 * another one. It works as a control, so it is `plain`.
 */
const ReplaceHistory = () => (
  <NextLink look="plain" href="/events" replace>
    Back to events
  </NextLink>
);

/**
 * The current page in a navigation: `aria-current="page"` tells screen
 * readers which link they're on. The nav itself is named, and its links are
 * `plain`: they work as controls.
 */
const Navigation = () => (
  <nav aria-label="Event sections">
    <ul className="flex-row-gap-4">
      <li>
        <NextLink look="plain" href="/events/42" aria-current="page">
          Overview
        </NextLink>
      </li>
      <li>
        <NextLink look="plain" href="/events/42/sessions">
          Sessions
        </NextLink>
      </li>
      <li>
        <NextLink look="plain" href="/events/42/attendees">
          Attendees
        </NextLink>
      </li>
    </ul>
  </nav>
);

/**
 * Disabled with a reason: it can't be followed, and hovering or focusing it
 * says why.
 */
const DisabledWithReason = () => (
  <NextLink
    href="/events/42/report"
    disabledWithReason="Opens once the event has ended"
  >
    Attendance report
  </NextLink>
);

/**
 * `onNavigate` runs before a route change and can cancel it with
 * `event.preventDefault()`. Here it blocks the navigation while the title has
 * unsaved changes, and a visible message says why.
 */
const GuardedNavigation = () => {
  const [saved, setSaved] = useState('Design review');
  const [title, setTitle] = useState(saved);
  const [blocked, setBlocked] = useState(false);
  const unsaved = title !== saved;

  return (
    <div className="flex-col-gap-2 items-start">
      <Input
        label="Event title"
        autoComplete="off"
        value={title}
        onChange={setTitle}
      />
      <Button
        variant="base"
        onClick={() => {
          setSaved(title);
          setBlocked(false);
        }}
      >
        Save
      </Button>
      <NextLink
        look="plain"
        href="/events"
        onNavigate={(event) => {
          if (!unsaved) return;
          event.preventDefault();
          setBlocked(true);
        }}
      >
        Back to all events
      </NextLink>
      <p role="status">{blocked ? 'Save your changes before leaving.' : ''}</p>
    </div>
  );
};

/**
 * A route styled as a button: `Button as={NextLink}` with `href`. A disabled
 * one renders an anchor without `href`, so it can't be followed; give a
 * reason.
 */
const RouteAsButton = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button as={NextLink} href="/events/new" leftIcon={<Plus />}>
      Create event
    </Button>
    <Button
      as={NextLink}
      href="/events/42/report"
      variant="base"
      disabledWithReason="Opens once the event has ended"
    >
      Attendance report
    </Button>
  </div>
);

export default function NextLinkRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <InText />
      <KeepScroll />
      <ReplaceHistory />
      <Navigation />
      <DisabledWithReason />
      <GuardedNavigation />
      <RouteAsButton />
    </div>
  );
}

// packages/ui/src/FormControl/FormControl.recipe.tsx
// Covers: ControlBox, ControlLabel, ControlMessage, FormControl

/**
 * FormControl: a form control's label, box, help text and status message around
 * a control you render yourself. Its children get `controlProps` to spread,
 * last, on the one focusable element.
 *
 * When not to use:
 * - A text, number, password or search field: Input, NumberInput,
 *   PasswordInput, SearchInput.
 * - A choice from a list: Select or MultiSelect. A yes/no choice: Checkbox.
 * - A date: DateInput.
 * - Only for a control the design system has no component for, like a native
 *   time input or the star rating below.
 *
 * Pitfalls:
 * - A button that acts on the field's value, such as Send, Apply or Move,
 *   goes in its `action`, in a form or out of one, such as a filter bar or a
 *   toolbar. A button beside the field in a flex row lines up with the label,
 *   not the box.
 * - Spread `controlProps` on one focusable element. Take `isDisabled` out first
 *   (it isn't an attribute) and stop the control changing while it's true:
 *   FormControl sets `tabIndex` and `aria-disabled`, not `disabled`.
 * - In a form, `{...field}` goes on FormControl and `value`, `onChange` and
 *   `onBlur` on the control.
 * - `withControlBox={false}` is for a control that draws its own box: render
 *   `ControlBox` and give it the props FormControl passes.
 * - A `role="slider"` needs `aria-valuenow`, `aria-valuemin`, `aria-valuemax`
 *   and the keyboard: arrows, Home and End.
 */
import { Button } from '@packages/ui/Button';
import { Controller, Form } from '@packages/ui/Form';
import {
  ControlBox,
  FormControl,
  type ControlProps,
} from '@packages/ui/FormControl';
import { Clock, Star } from 'lucide-react';
import React, { type KeyboardEvent, type MouseEvent, useId } from 'react';
import { useForm } from 'react-hook-form';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
// Stand in for requests to a server.
const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
const saveDoorsTime = (form: DoorsTimeForm) => wait(400).then(() => form);
const sendReview = (review: Review) => wait(400).then(() => review);

// Usage: the patterns to copy.
const STARS = 5;
const steps: Record<string, number> = {
  ArrowRight: 1,
  ArrowUp: 1,
  ArrowLeft: -1,
  ArrowDown: -1,
};

type RatingControlProps = {
  value: number;
  onChange: (value: number) => void;
  isDisabled: boolean;
};

// The slider's attributes and handlers, for a control that draws the stars.
const ratingProps = ({ value, onChange, isDisabled }: RatingControlProps) => {
  const rate = (next: number) => {
    if (!isDisabled) onChange(Math.min(STARS, Math.max(0, next)));
  };

  return {
    role: 'slider',
    'aria-valuemin': 0,
    'aria-valuemax': STARS,
    'aria-valuenow': value,
    'aria-valuetext': value ? `${value} of ${STARS} stars` : 'Not rated',
    onKeyDown: (event: KeyboardEvent) => {
      if (event.key === 'Home') rate(0);
      else if (event.key === 'End') rate(STARS);
      else if (steps[event.key]) rate(value + steps[event.key]);
      else return;
      event.preventDefault();
    },
    onClick: (event: MouseEvent<HTMLElement>) => {
      const { left, width } = event.currentTarget.getBoundingClientRect();
      rate(Math.ceil(((event.clientX - left) / width) * STARS));
    },
  };
};

const Stars = ({ value }: { value: number }) =>
  Array.from({ length: STARS }, (_, index) => (
    <Star
      key={index}
      aria-hidden
      fill={index < value ? 'currentColor' : 'none'}
    />
  ));

type DoorsTimeForm = { time: string };

/**
 * A native control inside the box. Every shared prop works as on Input:
 * `label`, `hint`, `helpText`, `required`, `size`, `variant`, `look`, an icon,
 * `tooltip`, `labelRightSlot`. `isDisabled` covers the disabled, read-only and
 * loading states, so the input is read-only while it's true.
 */
const DoorsTime = () => {
  const { control, handleSubmit } = useForm<DoorsTimeForm>({
    defaultValues: { time: '' },
  });

  return (
    <Form
      onSubmit={handleSubmit(saveDoorsTime)}
      actions={<Button type="submit">Save time</Button>}
    >
      <Controller
        name="time"
        control={control}
        rules={{ required: 'Pick when the doors open' }}
      >
        {({ field: { value, onChange, onBlur, ...field } }) => (
          <FormControl
            label="Doors open"
            hint="In the venue's time zone"
            helpText="Attendees can arrive from then"
            leftIcon={<Clock />}
            {...field}
          >
            {({ isDisabled, ...controlProps }) => (
              <input
                {...controlProps}
                type="time"
                value={value}
                readOnly={isDisabled}
                onChange={(event) => {
                  if (!isDisabled) onChange(event.target.value);
                }}
                onBlur={onBlur}
              />
            )}
          </FormControl>
        )}
      </Controller>
    </Form>
  );
};

/**
 * The states, each with its reason: `disabledWithReason`, `readOnlyWithReason`,
 * `loadingWithReason`, and the statuses `warning` and `success`.
 * `aria-labelledby` names a control with no `label` from a heading.
 */
const DateStates = () => {
  const headingId = useId();

  return (
    <div className="flex-col-gap-4 items-start">
      <h3 id={headingId}>Doors open</h3>
      <FormControl
        aria-labelledby={headingId}
        warning="Earlier than last year"
        size="sm"
        variant="base"
        look="open"
      >
        {({ isDisabled, ...controlProps }) => (
          <input
            {...controlProps}
            type="time"
            defaultValue="08:00"
            readOnly={isDisabled}
          />
        )}
      </FormControl>
      <FormControl
        label="Start time"
        disabledWithReason="Times lock once tickets are on sale"
      >
        {({ isDisabled, ...controlProps }) => (
          <input
            {...controlProps}
            type="time"
            defaultValue="18:00"
            readOnly={isDisabled}
          />
        )}
      </FormControl>
      <FormControl
        label="End time"
        readOnlyWithReason="The end follows the start"
        success="Matches the schedule"
      >
        {({ isDisabled, ...controlProps }) => (
          <input
            {...controlProps}
            type="time"
            defaultValue="21:00"
            readOnly={isDisabled}
          />
        )}
      </FormControl>
      <FormControl label="Rain start" loadingWithReason="Checking the forecast">
        {({ isDisabled, ...controlProps }) => (
          <input {...controlProps} type="time" readOnly={isDisabled} />
        )}
      </FormControl>
    </div>
  );
};

type Review = { rating: number };

/**
 * A custom control in the box: a slider of stars, 0 meaning "Not rated".
 * Arrows, Home and End move it, a press picks a star, and its value attributes
 * are what assistive tech reads.
 */
const EventRating = () => {
  const { control, handleSubmit } = useForm<Review>({
    defaultValues: { rating: 0 },
  });

  return (
    <Form
      onSubmit={handleSubmit(sendReview)}
      actions={<Button type="submit">Send</Button>}
    >
      <Controller
        name="rating"
        control={control}
        rules={{
          min: { value: 1, message: 'Rate the event from 1 to 5 stars' },
        }}
      >
        {({ field: { value, onChange, onBlur, ...field } }) => (
          <FormControl
            label="Your rating"
            hint="Shown to the organizer only"
            {...field}
          >
            {({ isDisabled, ...controlProps }: ControlProps) => (
              <div
                {...ratingProps({ value, onChange, isDisabled })}
                onBlur={onBlur}
                className="flex-row-gap-1 items-center"
                {...controlProps}
              >
                <Stars value={value} />
              </div>
            )}
          </FormControl>
        )}
      </Controller>
    </Form>
  );
};

/**
 * A control that is its own box: `withControlBox={false}` and `ControlBox`
 * around the stars. FormControl hands the box its look and state through
 * `controlProps`: spread them all on `ControlBox`.
 */
const BoxedRating = () => {
  const { control } = useForm<Review>({ defaultValues: { rating: 3 } });

  return (
    <Controller name="rating" control={control}>
      {({ field: { value, onChange, onBlur, ...field } }) => (
        <FormControl label="Venue rating" withControlBox={false} {...field}>
          {({ isDisabled, ...controlProps }) => (
            <ControlBox
              {...controlProps}
              isDisabled={isDisabled}
              {...ratingProps({ value, onChange, isDisabled })}
              onBlur={onBlur}
            >
              <Stars value={value} />
            </ControlBox>
          )}
        </FormControl>
      )}
    </Controller>
  );
};

export default function FormControlRecipe() {
  return (
    <div className="flex-col-gap-6">
      <DoorsTime />
      <DateStates />
      <EventRating />
      <BoxedRating />
    </div>
  );
}

// packages/ui/src/Chip/Chip.recipe.tsx
// Covers: Chip, ChipGroup

/**
 * Chip: a compact toggle showing whether it's on, for filters and quick choices
 * that stay visible. A ChipGroup holds 2 to about 8: one choice
 * (`mode="single"`, the default, read as radio buttons) or any number
 * (`mode="multiple"`, read as checkboxes). One chip on its own is an
 * independent on/off filter.
 *
 * When not to use:
 * - A chosen value the user removes ("Region: Europe"): Tag with `closable`.
 * - An action (save, delete, open a menu): Button.
 * - More than about 8 options, or long labels: Select, or MultiSelect.
 * - A yes/no answer in a form, with a label: Checkbox.
 *
 * Pitfalls:
 * - A ChipGroup needs a name: `label`, `aria-labelledby` pointing at a visible
 *   heading, or `aria-label` when nothing visible asks the question.
 * - In a form, a ChipGroup is the field: spread Controller's `{...field}` on
 *   it. It brings its own label, help text and error; don't wrap it in a
 *   FormControl.
 * - `mode` defaults to single. Set `mode="multiple"` for several at once.
 * - Every chip in a group needs a `value`.
 * - In a group, the mode picks the look (outline for single, filled for
 *   multiple); `look` on its chips can't override it.
 * - A bare count in a chip means nothing read aloud: give it a unit in visually
 *   hidden text ("12 tickets").
 * - `look="collapsed"` on a ChipGroup lays its chips out as one bar that
 *   doesn't wrap: keep it to a few short labels, and give it no layout
 *   `className`.
 * - Say why a chip can't be changed: `disabledWithReason`,
 *   `readOnlyWithReason`, not a bare `disabled`. A ChipGroup takes
 *   `disabledWithReason` too.
 */
import { Button } from '@packages/ui/Button';
import { Chip, ChipGroup } from '@packages/ui/Chip';
import { Controller, Form } from '@packages/ui/Form';
import { Star, Ticket } from 'lucide-react';
import React, { useId, useState } from 'react';
import { useForm } from 'react-hook-form';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const ranges = [
  { value: '7d', label: '7 days' },
  { value: '30d', label: '30 days' },
  { value: '90d', label: '90 days' },
];

const statuses = ['Draft', 'Published', 'Sold out', 'Cancelled'];

const tracks = ['Design', 'Engineering', 'Product', 'Research'];

// Stands in for a request to a server.
const saveInterests = (interests: Interests) =>
  new Promise((resolve) => setTimeout(resolve, 400, interests));

// Usage: the patterns to copy.
/**
 * Single choice: exactly one option is on, like a radio group (a date range, a
 * view mode). Picking one turns the other off. A visible heading names the
 * group via `aria-labelledby`. `look="collapsed"` joins the chips into one
 * bar.
 */
const SingleChoice = () => {
  const [range, setRange] = useState('30d');
  const headingId = useId();

  return (
    <div className="flex-col-gap-2">
      <h3 id={headingId}>Show events from the last</h3>
      <ChipGroup
        mode="single"
        aria-labelledby={headingId}
        value={range}
        onChange={setRange}
        look="collapsed"
      >
        {ranges.map(({ value, label }) => (
          <Chip key={value} value={value}>
            {label}
          </Chip>
        ))}
      </ChipGroup>
    </div>
  );
};

/**
 * Multiple choice: any number of options on, like checkboxes (status
 * filters). With no heading to point at, `aria-label` names the group.
 */
const MultipleChoice = () => {
  const [selected, setSelected] = useState<string[]>(['Published']);

  return (
    <ChipGroup
      mode="multiple"
      aria-label="Event status"
      value={selected}
      onChange={setSelected}
      className="flex-row-gap-2 flex-wrap"
    >
      {statuses.map((status) => (
        <Chip key={status} value={status}>
          {status}
        </Chip>
      ))}
    </ChipGroup>
  );
};

/**
 * Independent toggle: one chip on its own, on or off (a "Starred only" filter),
 * controlled with `active` and `onActiveChange`. `leftIcon` is decoration: the
 * text names it.
 */
const IndependentToggle = () => {
  const [starredOnly, setStarredOnly] = useState(false);

  return (
    <Chip
      leftIcon={<Star />}
      active={starredOnly}
      onActiveChange={setStarredOnly}
    >
      Starred only
    </Chip>
  );
};

/**
 * Starts on: begin the state as `true`. `tooltip` adds detail on hover and
 * focus.
 */
const StartsOn = () => {
  const [available, setAvailable] = useState(true);

  return (
    <Chip
      active={available}
      onActiveChange={setAvailable}
      tooltip="Events with at least one ticket left"
      rightIcon={<Ticket />}
    >
      Tickets available
    </Chip>
  );
};

/**
 * Count after the label: `rightAddOn` takes an element. Screen readers get the
 * count with its unit from hidden text, and skip the visual number.
 */
const WithCount = () => {
  const [paid, setPaid] = useState(true);

  return (
    <Chip
      active={paid}
      onActiveChange={setPaid}
      rightAddOn={<span aria-hidden>12</span>}
    >
      Paid tickets
      <span className="sr-only"> (12 tickets)</span>
    </Chip>
  );
};

/**
 * States: `disabledWithReason`, `readOnlyWithReason` and `loadingWithReason`
 * say why on hover and to screen readers. Loading chips stay put and can't be
 * pressed until done.
 */
const States = () => {
  const [on, setOn] = useState(true);

  return (
    <div className="flex-row-gap-2 flex-wrap">
      <Chip
        active={on}
        onActiveChange={setOn}
        disabledWithReason="Early bird sales have ended"
      >
        Early bird
      </Chip>
      <Chip
        active={on}
        onActiveChange={setOn}
        readOnlyWithReason="Set by the organizer"
      >
        Featured
      </Chip>
      <Chip loadingWithReason="Updating the attendee list">Checked in</Chip>
    </div>
  );
};

/**
 * A disabled group: `disabledWithReason` on the ChipGroup disables every chip
 * and gives each the reason; a chip's own reason wins. `disabled` disables the
 * group silently.
 */
const DisabledGroup = () => {
  const [ticket, setTicket] = useState('general');

  return (
    <ChipGroup
      disabledWithReason="Ticket type is fixed after checkout"
      aria-label="Ticket type"
      value={ticket}
      onChange={setTicket}
      className="flex-row-gap-2 flex-wrap"
    >
      <Chip value="general">General</Chip>
      <Chip value="vip">VIP</Chip>
      <Chip value="speaker" disabledWithReason="Speakers are invited">
        Speaker
      </Chip>
    </ChipGroup>
  );
};

type Interests = { tracks: string[] };

/**
 * In a form: the ChipGroup is the field, rendered through Controller with
 * `{...field}`. `label` names it, `helpText` says what's asked, and the rule's
 * message shows as its error on a failed submit.
 */
const InterestsForm = () => {
  const [status, setStatus] = useState('');
  const { control, handleSubmit } = useForm<Interests>({
    defaultValues: { tracks: [] },
  });

  const submit = async (interests: Interests) => {
    await saveInterests(interests);
    setStatus(`Saved ${interests.tracks.join(', ')}`);
  };

  return (
    <Form
      onSubmit={handleSubmit(submit)}
      actions={<Button type="submit">Save</Button>}
    >
      <Controller
        name="tracks"
        control={control}
        rules={{
          validate: (value) => value.length > 0 || 'Pick at least one track',
        }}
      >
        {({ field }) => (
          <ChipGroup
            mode="multiple"
            label="Tracks"
            helpText="We'll suggest sessions from these."
            {...field}
            className="flex-row-gap-2 flex-wrap"
          >
            {tracks.map((track) => (
              <Chip key={track} value={track}>
                {track}
              </Chip>
            ))}
          </ChipGroup>
        )}
      </Controller>
      <p role="status">{status}</p>
    </Form>
  );
};

export default function ChipRecipe() {
  return (
    <div className="flex-col-gap-6">
      <SingleChoice />
      <MultipleChoice />
      <IndependentToggle />
      <StartsOn />
      <WithCount />
      <States />
      <DisabledGroup />
      <InterestsForm />
    </div>
  );
}

